-- Portal de Faturamento · T1a, semente do catálogo de serviços (migration de dados, 20/10/2026).
--
-- Gerada por PM Work/execution/portal-faturamento-prd-20261013/e1/gerar_servicos_e0.py a partir de
-- e0/levantamento.json (Omie de cada emissora, ListarCadastroServico, lido em 15/10/2026 às 11:50).
-- 138 serviços de 15 emissoras, 130 ativos (126 ativos com tributação). A emissora é casada pelo CNPJ.
-- Depende de 20261020100000_portal_faturamento_t1a.sql (colunas codigo, id_tributacao e tem_tributacao).
-- Rollback: supabase/rollback/20261020101000_portal_faturamento_servicos_e0_rollback.sql
-- Ensaio: junto com a T1a, em supabase/gates/20261020_portal_faturamento_t1a.sql (bloco S).
--
-- É uma foto do cadastro: sincronizado_em = 2026-10-15 11:50:00-03. A carga periódica (Integrações) atualiza depois.
-- Linha que já existir (mesma emissora e nCodServ) fica como está.

begin;

create temporary table _servicos_e0 (
  cnpj text, codigo_omie text, codigo text, descricao text, codigo_lc116 text, codigo_municipal text,
  id_tributacao text, tributacao jsonb, categoria text, ativo boolean, tem_tributacao_e0 boolean
) on commit drop;


   categoria_padrao, ativo, sincronizado_em)
select g.id, s.codigo_omie, s.codigo, s.descricao, s.codigo_lc116, s.codigo_municipal, s.id_tributacao, s.tributacao,
       s.categoria, s.ativo, timestamptz '2026-10-15 11:50:00-03'
  from _servicos_e0 s
  join organizacao.empresas_grupo g on g.cnpj = s.cnpj
on conflict (emissora_id, codigo_omie) do nothing;

do $conferencia$
declare
  n int;
  r record;
begin
  select count(*) into n from _servicos_e0 s
   where not exists (select 1 from organizacao.empresas_grupo g where g.cnpj = s.cnpj);
  if n <> 0 then raise exception 'Semente E0: % serviços sem emissora casada pelo CNPJ', n; end if;

  for r in
    select v.cnpj, v.total, v.ativos,
           count(f.id) as total_banco, count(f.id) filter (where f.ativo) as ativos_banco
      from (values
    ('49726267000150', 42, 42),  -- DOC
    ('44275738000137', 7, 5),  -- BPO
    ('23632609000189', 7, 7),  -- PGE
    ('30459798000103', 9, 9),  -- PMC_MAROX
    ('55950467000194', 7, 7),  -- MAROX_SERVICOS
    ('66532907000100', 4, 4),  -- NEO
    ('24296850000147', 11, 11),  -- PAC
    ('58565726000151', 10, 10),  -- PARTNERS
    ('40949469000196', 10, 4),  -- PAT
    ('23527887000176', 9, 9),  -- PCC
    ('40417435000150', 2, 2),  -- PIS
    ('59639455000102', 6, 6),  -- SP
    ('24600951000160', 1, 1),  -- PNC
    ('55909495000168', 5, 5),  -- RJ
    ('48790748000161', 8, 8)  -- ROIT
      ) as v (cnpj, total, ativos)
      join organizacao.empresas_grupo g on g.cnpj = v.cnpj
      left join receita.fat_servicos f on f.emissora_id = g.id and f.sincronizado_em = timestamptz '2026-10-15 11:50:00-03'
     group by v.cnpj, v.total, v.ativos
  loop
    if r.total_banco <> r.total or r.ativos_banco <> r.ativos then
      raise exception 'Semente E0: CNPJ % com % serviços (% ativos) no banco; o E0 tem % (% ativos)',
        r.cnpj, r.total_banco, r.ativos_banco, r.total, r.ativos;
    end if;
  end loop;

  select count(*) into n from receita.fat_servicos where sincronizado_em = timestamptz '2026-10-15 11:50:00-03';
  if n <> 138 then raise exception 'Semente E0: % serviços gravados (esperava 138)', n; end if;

  select count(*) into n
    from _servicos_e0 s
    join organizacao.empresas_grupo g on g.cnpj = s.cnpj
    join receita.fat_servicos f on f.emissora_id = g.id and f.codigo_omie = s.codigo_omie
   where f.tem_tributacao is distinct from s.tem_tributacao_e0;
  if n <> 0 then raise exception 'Semente E0: tem_tributacao do banco diverge do E0 em % serviços', n; end if;
end $conferencia$;

commit;
